ITextSource source = SourceFactory.Create("memory");
Console.WriteLine(source.Read());

interface ITextSource { string Read(); }
class MemorySource : ITextSource
{
    public string Read() => "Nội dung từ bộ nhớ";
}
static class SourceFactory
{
    public static ITextSource Create(string kind) => kind switch
    {
        "memory" => new MemorySource(),
        _ => throw new ArgumentException("Nguồn không hỗ trợ", nameof(kind))
    };
}
